                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        keep = (state + weight + i) % 7 != 1 or i == len(rows) - 1
        if keep:
            kept_rows.append(row)

        if weight == 0:
            state = 5
        else:
            state = (3 * state + weight) % 7

    final_state = state
    kept_length = len(kept_rows)
    if kept_length > 0:
        rotation_amount = final_state % kept_length
        kept_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    aggregated_amounts = collections.defaultdict(int)
